<?php
return function(Router $r){
    $r->get('/work',function(){
        $workspaces=WorkService::workspaces();$workspace=null;if(isset($_GET['workspace']))$workspace=WorkService::workspace(record_id($_GET['workspace']));elseif($workspaces)$workspace=$workspaces[0];$tab=$_GET['tab']??'overview';if(!is_string($tab)||!in_array($tab,['overview','projects','mine','intake','people','settings','archived'],true))throw new InvalidArgumentException('Choose a work-management page.');
        return View::render(__DIR__.'/views/home.php',['title'=>'Work management','workspaces'=>$workspaces,'workspace'=>$workspace,'tab'=>$tab,'overview'=>$workspace?WorkPlanningService::overview((int)$workspace['id']):null,'people'=>$workspace?WorkService::people((int)$workspace['id']):[],'websites'=>WebsiteService::profiles()]);
    });
    $r->post('/work/workspace',function(){$id=WorkService::saveWorkspace($_POST);return redirect('/work?workspace='.$id,'Workspace created. Add your first project.');});
    $r->post('/work/workspace/{workspace}/save',function($p){$id=record_id($p['workspace']);WorkService::saveWorkspace($_POST,$id);return redirect('/work?workspace='.$id.'&tab=settings','Workspace updated.');});
    $r->post('/work/workspace/{workspace}/people',function($p){$w=record_id($p['workspace']);WorkService::savePerson($w,$_POST,optional_id($_POST['person_id']??''));return redirect('/work?workspace='.$w.'&tab=people','Assignee saved. This is a local workspace contact, not a cloud login.');});
    $r->post('/work/workspace/{workspace}/projects',function($p){$id=WorkService::saveProject(record_id($p['workspace']),$_POST);return redirect('/work/project/'.$id,'Project created with its own workflow.');});
    $r->get('/work/project/{project}',function($p){
        $id=record_id($p['project']);$project=WorkService::project($id);$tab=$_GET['tab']??'issues';if(!is_string($tab)||!in_array($tab,['issues','cycles','modules','releases','pages','views','analytics','activity','settings'],true))throw new InvalidArgumentException('Choose a project page.');$input=$_GET;$layout=$_GET['layout']??'list';$view=null;
        if(isset($_GET['view_id'])){$view=WorkService::scoped('work_views',$id,record_id($_GET['view_id']));$input=array_merge(json_decode($view['filters'],true,32,JSON_THROW_ON_ERROR),$_GET);$layout=$_GET['layout']??$view['layout'];}
        if(!is_string($layout)||!isset(WorkService::LAYOUTS[$layout]))throw new InvalidArgumentException('Choose a supported work-item layout.');
        $month=$_GET['month']??date('Y-m');if(!is_string($month))throw new InvalidArgumentException('Choose a valid calendar month.');$month=valid_month($month);
        if(in_array($layout,['calendar','gantt'],true)){$input['range_from']=$month.'-01';$input['range_to']=(new DateTimeImmutable($month.'-01'))->modify('last day of this month')->format('Y-m-d');$input['range_mode']=$layout==='gantt'?'overlap':'due';}
        $listing=WorkIssueService::listing($id,$input,int_range($_GET['page']??1,1,1000000),in_array($layout,['calendar','gantt'],true)?500:100);
        return View::render(__DIR__.'/views/project.php',['title'=>$project['name'].' · Work','workspace'=>WorkService::workspace((int)$project['workspace_id']),'project'=>$project,'tab'=>$tab,'layout'=>$layout,'month'=>$month,'listing'=>$listing,'savedView'=>$view,'states'=>WorkService::states($id),'labels'=>WorkService::labels($id),'people'=>WorkService::people((int)$project['workspace_id']),'cycles'=>WorkService::groupings($id,'cycle'),'modules'=>WorkService::groupings($id,'module'),'releases'=>WorkReleaseService::listing($id),'pages'=>Db::all('SELECT * FROM work_pages WHERE project_id=? AND deleted_at IS NULL ORDER BY pinned DESC,updated_at DESC,id DESC',[$id]),'views'=>Db::all('SELECT * FROM work_views WHERE project_id=? ORDER BY name',[$id]),'analytics'=>WorkPlanningService::analytics($id),'websites'=>WebsiteService::profiles()]);
    });
    $r->get('/work/issue/{issue}',function($p){
        $issue=WorkIssueService::get(record_id($p['issue']));$id=(int)$issue['project_id'];$project=WorkService::project($id);
        return View::render(__DIR__.'/views/issue.php',['title'=>$issue['key'].' · '.$issue['title'],'workspace'=>WorkService::workspace((int)$project['workspace_id']),'project'=>$project,'issue'=>$issue,'states'=>WorkService::states($id),'labels'=>WorkService::labels($id),'people'=>WorkService::people((int)$project['workspace_id']),'cycles'=>WorkService::groupings($id,'cycle'),'modules'=>WorkService::groupings($id,'module'),'releases'=>WorkReleaseService::listing($id),'comments'=>Db::all('SELECT c.*,p.name author_name FROM work_comments c JOIN work_people p ON p.id=c.author_id WHERE c.issue_id=? AND c.deleted_at IS NULL ORDER BY c.id',[$issue['id']]),'children'=>Db::all('SELECT i.*,s.name state_name,s.color state_color FROM work_issues i JOIN work_states s ON s.id=i.state_id WHERE i.parent_id=? AND i.deleted_at IS NULL ORDER BY i.sequence',[$issue['id']]),'relations'=>Db::all('SELECT * FROM work_relations WHERE from_id=? OR to_id=? ORDER BY id',[$issue['id'],$issue['id']]),'timeEntries'=>Db::all('SELECT t.*,p.name person_name FROM work_time_entries t JOIN work_people p ON p.id=t.person_id WHERE t.issue_id=? ORDER BY t.on_date DESC,t.id DESC',[$issue['id']]),'attachments'=>Db::all('SELECT a.id,d.* FROM work_attachments a JOIN documents d ON d.id=a.document_id WHERE a.issue_id=?',[$issue['id']]),'timer'=>Db::one('SELECT * FROM work_timers WHERE issue_id=?',[$issue['id']]),'relatedChoices'=>Db::all('SELECT id,sequence,title FROM work_issues WHERE project_id=? AND id<>? AND deleted_at IS NULL ORDER BY sequence DESC LIMIT 500',[$id,$issue['id']]),'activity'=>Db::all('SELECT a.*,p.name actor_name FROM work_activity a JOIN work_people p ON p.id=a.actor_id WHERE a.issue_id=? ORDER BY a.id DESC LIMIT 50',[$issue['id']])]);
    });
    $r->post('/work/project/{project}/issues',function($p){$id=WorkIssueService::save(record_id($p['project']),$_POST);return redirect('/work/issue/'.$id,'Work item created.');});
    $r->post('/work/project/{project}/issues/{issue}/save',function($p){$data=$_POST;if(isset($data['assignees_present']))$data['assignee_ids']=$data['assignee_ids']??[];if(isset($data['labels_present']))$data['label_ids']=$data['label_ids']??[];$id=record_id($p['issue']);WorkIssueService::save(record_id($p['project']),$data,$id);return redirect('/work/issue/'.$id,'Work item updated.');});
    $r->post('/work/project/{project}/issues/{issue}/field',function($p){$field=text_input('field',30);if(!in_array($field,['title','state_id','priority','cycle_id','module_id','due_date','estimate','issue_type','fix_version_id'],true))throw new InvalidArgumentException('Choose an editable spreadsheet field.');WorkIssueService::save(record_id($p['project']),[$field=>$_POST['value']??'','version'=>$_POST['version']??''],record_id($p['issue']));return redirect('/work/project/'.record_id($p['project']).'?layout=spreadsheet','Spreadsheet cell saved.');});
    $r->post('/work/project/{project}/issues/{issue}/move',function($p){$project=record_id($p['project']);$issue=record_id($p['issue']);WorkIssueService::move($project,$issue,record_id($_POST['state_id']??''),int_range($_POST['version']??'',1,PHP_INT_MAX));if(($_SERVER['HTTP_X_REQUESTED_WITH']??'')==='LifeOS-Work-Board'){header('Content-Type: application/json');return json_encode(['ok'=>true,'version'=>(int)WorkIssueService::get($issue)['version']],JSON_THROW_ON_ERROR);}return redirect('/work/project/'.$project.'?layout=board','Work item moved.');});
    $r->post('/work/project/{project}/issues/{issue}/lifecycle',function($p){$id=record_id($p['issue']);WorkIssueService::lifecycle(record_id($p['project']),$id,text_input('action',20),int_range($_POST['version']??'',1,PHP_INT_MAX));return redirect('/work/issue/'.$id,'Work item state updated. History is preserved.');});
    $r->post('/work/project/{project}/bulk',function($p){$ids=$_POST['ids']??[];$versions=$_POST['versions']??[];if(!is_array($ids)||!is_array($versions))throw new InvalidArgumentException('Choose valid work items.');WorkIssueService::bulk(record_id($p['project']),$ids,$versions,text_input('field',30),$_POST['value']??'');return redirect('/work/project/'.record_id($p['project']),'Selected work items updated together.');});
    $r->post('/work/project/{project}/save',function($p){$project=WorkService::project(record_id($p['project']));WorkService::saveProject((int)$project['workspace_id'],$_POST,(int)$project['id']);return redirect('/work/project/'.$project['id'].'?tab=settings','Project updated.');});
    $r->post('/work/project/{project}/archive',function($p){$project=WorkService::project(record_id($p['project']));WorkService::archiveProject((int)$project['id'],($_POST['restore']??'0')==='1');return redirect('/work?workspace='.$project['workspace_id'].'&tab=archived','Project archive updated. All records were preserved.');});
    foreach(['state','label'] as $kind)$r->post('/work/project/{project}/'.$kind,function($p)use($kind){$id=record_id($p['project']);$item=optional_id($_POST['item_id']??'');if($kind==='state')WorkService::saveState($id,$_POST,$item);else WorkService::saveLabel($id,$_POST,$item);return redirect('/work/project/'.$id.'?tab=settings',ucfirst($kind).' saved.');});
    $r->post('/work/project/{project}/release',function($p){$id=record_id($p['project']);WorkReleaseService::save($id,$_POST,optional_id($_POST['release_id']??''));return redirect('/work/project/'.$id.'?tab=releases','Release saved.');});
    $r->post('/work/project/{project}/state/{state}/remove',function($p){$id=record_id($p['project']);WorkPlanningService::removeState($id,record_id($p['state']),record_id($_POST['replacement']??''));return redirect('/work/project/'.$id.'?tab=settings','Workflow state removed and all affected items reassigned.');});
    $r->post('/work/project/{project}/label/{label}/remove',function($p){$id=record_id($p['project']);$label=record_id($p['label']);WorkService::scoped('work_labels',$id,$label);Db::run('DELETE FROM work_labels WHERE id=?',[$label]);return redirect('/work/project/'.$id.'?tab=settings','Label removed. Work items were kept.');});
    foreach(['cycle','module'] as $kind)$r->post('/work/project/{project}/'.$kind,function($p)use($kind){$id=record_id($p['project']);WorkService::saveGrouping($id,$kind,$_POST,optional_id($_POST['item_id']??''));return redirect('/work/project/'.$id.'?tab='.($kind==='cycle'?'cycles':'modules'),ucfirst($kind).' saved.');});
    $r->post('/work/project/{project}/cycle/{cycle}/complete',function($p){$id=record_id($p['project']);WorkPlanningService::completeCycle($id,record_id($p['cycle']),optional_id($_POST['move_to']??''));return redirect('/work/project/'.$id.'?tab=cycles','Cycle completed. Unfinished items were moved only if a target cycle was selected.');});
    $r->post('/work/project/{project}/views',function($p){$id=record_id($p['project']);$view=WorkPlanningService::saveView($id,$_POST,optional_id($_POST['view_id']??''));return redirect('/work/project/'.$id.'?view_id='.$view,'View saved with its filters and layout.');});
    $r->post('/work/project/{project}/view/{view}/remove',function($p){$id=record_id($p['project']);$view=record_id($p['view']);WorkService::scoped('work_views',$id,$view);Db::run('DELETE FROM work_views WHERE id=?',[$view]);return redirect('/work/project/'.$id.'?tab=views','Saved view removed. Work items were kept.');});
    $r->get('/work/project/{project}/page/{page}',function($p){$project=WorkService::project(record_id($p['project']));$page=WorkService::scoped('work_pages',(int)$project['id'],record_id($p['page']));return View::render(__DIR__.'/views/page.php',['title'=>$page['title'],'project'=>$project,'workspace'=>WorkService::workspace((int)$project['workspace_id']),'page'=>$page,'versions'=>Db::all('SELECT version,created_at FROM work_page_versions WHERE page_id=? ORDER BY version DESC',[$page['id']]),'linked'=>Db::all('SELECT i.id,i.title,i.sequence FROM work_issues i JOIN work_page_issues l ON l.issue_id=i.id WHERE l.page_id=? AND i.deleted_at IS NULL',[$page['id']])]);});
    $r->post('/work/project/{project}/pages',function($p){$id=record_id($p['project']);$page=WorkService::savePage($id,$_POST,optional_id($_POST['page_id']??''));return redirect('/work/project/'.$id.'/page/'.$page,'Project page saved with version history.');});
    $r->post('/work/project/{project}/page/{page}/rollback',function($p){$id=record_id($p['project']);$page=record_id($p['page']);WorkPlanningService::rollbackPage($id,$page,int_range($_POST['version']??'',1,PHP_INT_MAX),int_range($_POST['target']??'',1,PHP_INT_MAX));return redirect('/work/project/'.$id.'/page/'.$page,'Earlier page content restored as a new version.');});
    $r->post('/work/project/{project}/page/{page}/issue',function($p){$issue=WorkPlanningService::pageToIssue(record_id($p['project']),record_id($p['page']),$_POST);return redirect('/work/issue/'.$issue,'Page content converted into a linked work item.');});
    $r->post('/work/project/{project}/page/{page}/trash',function($p){$project=record_id($p['project']);$page=WorkService::scoped('work_pages',$project,record_id($p['page']));if((int)$page['version']!==int_range($_POST['version']??'',1,PHP_INT_MAX))throw new InvalidArgumentException('This page changed. Reload before continuing.');Db::run('UPDATE work_pages SET deleted_at=?,version=version+1 WHERE id=?',[($_POST['restore']??'0')==='1'?null:gmdate('Y-m-d H:i:s'),$page['id']]);return redirect('/work/project/'.$project.'?tab=pages','Page trash updated. Content and history were preserved.');});
    $r->post('/work/issue/{issue}/comments',function($p){$id=record_id($p['issue']);WorkIssueService::comment($id,text_input('body',20000),optional_id($_POST['comment_id']??''),isset($_POST['version'])?int_range($_POST['version'],1,PHP_INT_MAX):null);return redirect('/work/issue/'.$id.'#work-comments','Comment saved.');});
    $r->post('/work/issue/{issue}/comment/{comment}/remove',function($p){$id=record_id($p['issue']);$comment=Db::one('SELECT * FROM work_comments WHERE id=? AND issue_id=?', [record_id($p['comment']),$id]);if(!$comment||(int)$comment['version']!==int_range($_POST['version']??'',1,PHP_INT_MAX))throw new InvalidArgumentException('Comment changed or was not found.');Db::run('UPDATE work_comments SET deleted_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=?',[$comment['id']]);return redirect('/work/issue/'.$id.'#work-comments','Comment removed from the conversation.');});
    $r->post('/work/issue/{issue}/relations',function($p){$id=record_id($p['issue']);$issue=WorkIssueService::get($id);WorkIssueService::relate((int)$issue['project_id'],$id,record_id($_POST['related_id']??''),text_input('kind',20));return redirect('/work/issue/'.$id.'#work-relations','Work items linked.');});
    $r->post('/work/issue/{issue}/relation/{relation}/remove',function($p){$id=record_id($p['issue']);$issue=WorkIssueService::get($id);$relation=Db::one('SELECT * FROM work_relations WHERE id=? AND project_id=? AND (from_id=? OR to_id=?)',[record_id($p['relation']),$issue['project_id'],$id,$id]);if(!$relation)throw new InvalidArgumentException('Relationship not found.');Db::run('DELETE FROM work_relations WHERE id=?',[$relation['id']]);return redirect('/work/issue/'.$id.'#work-relations','Relationship removed.');});
    $r->post('/work/issue/{issue}/time',function($p){$id=record_id($p['issue']);WorkIssueService::logTime($id,$_POST);return redirect('/work/issue/'.$id.'#work-time','Time entry saved.');});
    $r->post('/work/issue/{issue}/time/{entry}/remove',function($p){$id=record_id($p['issue']);WorkIssueService::get($id);$entry=Db::one('SELECT id FROM work_time_entries WHERE id=? AND issue_id=?',[record_id($p['entry']),$id]);if(!$entry)throw new InvalidArgumentException('Time entry not found.');Db::run('DELETE FROM work_time_entries WHERE id=?',[$entry['id']]);return redirect('/work/issue/'.$id.'#work-time','Time entry removed.');});
    $r->post('/work/issue/{issue}/timer',function($p){$id=record_id($p['issue']);if(($_POST['action']??'')==='start')WorkIssueService::startTimer($id);elseif(($_POST['action']??'')==='stop')WorkIssueService::stopTimer($id,$_POST['minutes']??'');else throw new InvalidArgumentException('Choose start or stop.');return redirect('/work/issue/'.$id.'#work-time','Timer updated.');});
    $r->post('/work/issue/{issue}/attachments',function($p){$id=record_id($p['issue']);$file=$_FILES['file']??null;if(!is_array($file))throw new InvalidArgumentException('Choose an attachment.');WorkIssueService::attach($id,$file);return redirect('/work/issue/'.$id.'#work-files','Attachment saved and included in encrypted LifeOS backups.');});
    $r->post('/work/workspace/{workspace}/favorite',function($p){$workspace=record_id($p['workspace']);WorkService::favorite($workspace,text_input('entity',20),record_id($_POST['entity_id']??''),($_POST['on']??'1')==='1');return redirect('/work?workspace='.$workspace,'Favourites updated.');});
    $r->get('/work/project/{project}/export.csv',function($p){$id=record_id($p['project']);$project=WorkService::project($id);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$project['identifier'].'-work-items.csv"');$out=fopen('php://output','wb');fputcsv($out,['Key','Title','State','Priority','Assignees','Start','Due','Estimate','Description','Type','Fix version']);$page=1;do{$batch=WorkIssueService::listing($id,$_GET,$page,500);foreach($batch['rows'] as $row){$cells=[$row['key'],$row['title'],$row['state_name'],WorkService::PRIORITIES[$row['priority']],implode(', ',array_column($row['assignees'],'name')),$row['start_date'],$row['due_date'],$row['estimate'],$row['description'],WorkService::TYPES[$row['issue_type']],$row['fix_version_name']??''];fputcsv($out,array_map(fn($v)=>is_string($v)&&preg_match('/^[=+@\-\t\r]/',$v)?"'".$v:$v,$cells));}$page++;}while($page<=$batch['pages']);fclose($out);return '';});
    $r->get('/work/project/{project}/export',function($p){$id=record_id($p['project']);$data=WorkPlanningService::export($id);header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="'.$data['project']['identifier'].'-project.json"');return json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);});
};
